t.target.blur()\n    }\n\n    return {\n      expanded,\n      objData,\n      onObjDataUpdate,\n      objDescription,\n      hasForBadge,\n      hasIfBadge,\n      nameValue,\n      schema,\n      serializableDefaults,\n      templateLockVisible,\n      templateLockPopoverOptions,\n      templateLockEl,\n      onTemplateLockKeyActivate,\n      toggleExpanded,\n      onChevronClick,\n      onNameInput,\n      onBlur,\n      commitAndBlur\n    }\n  }\n}\n</script>\n\n<style scoped>\n.obj-list-item-content {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n  width: 100%;\n}\n\n.obj-list-item-header {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  min-height: 32px;\n}\n\n.obj-list-item-chevron {\n  flex-shrink: 0;\n  width: 20px;\n  height: 20px;\n  padding: 0;\n  margin: 0;\n  border: none;\n  background: transparent;\n  color: rgba(255, 255, 255, 0.6);\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.obj-list-item-chevron:hover {\n  color: rgba(255, 255, 255, 0.85);\n}\n\n.obj-list-item-chevron-spacer {\n  flex-shrink: 0;\n  width: 20px;\n  height: 20px;\n}\n\n.obj-list-item-lock {\n  flex-shrink: 0;\n  width: 24px;\n  height: 24px;\n  padding: 0;\n  margin: 0;\n  margin-left: auto;\n  border: none;\n  background: transparent;\n  color: rgba(255, 255, 255, 0.9);\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n}\n\n.obj-list-item-lock--template {\n  cursor: pointer;\n  color: rgba(135, 206, 250, 0.95);\n}\n\n.obj-list-item-lock--template:hover {\n  color: rgba(135, 206, 250, 0.95);\n}\n\n.obj-list-item-lock-svg {\n  width: 14px;\n  height: 14px;\n}\n\n.obj-list-item-chevron-svg {\n  width: 10px;\n  height: 10px;\n  transition: transform 0.2s ease;\n}\n\n.obj-list-item-chevron-svg.is-expanded {\n  transform: rotate(90deg);\n}\n\n.obj-list-item-main {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: colu