#obj-bar {
  background-color: rgba(255, 255, 255, 0.3);
}
.obj-bar {
  z-index: -1;
  box-sizing: border-box;
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
  color:white;
  font-size:12pt;
  
  padding-top: 3px;
  padding-left: 12px;
  padding-right: 7px;
  padding-bottom: 3px;
  /* Keep it content-sized (not stretched by the column flex parent). */
  align-self: center;
  width: fit-content;
  max-width: 100%;
  /* Avoid vertical auto-margins, which would center it in the viewport. */
  margin: 16px auto 0;
  text-align: center;
  border-radius: 0.5em;
}
.obj-bar .btn {
  padding-top: 0;
  padding-left: 7px;
  padding-right: 7px;
  color: white;
}
.obj-bar .btn:focus {
  box-shadow: none;
}
.obj-bar-nobr {
  white-space: nowrap;
  padding-left: 3px;
  padding-right: 3px;
}
.obj-bar .obj-bar-nobr--highlighted {
  /* Atomic inline-level box: Chrome draws one outline; plain inline can fragment.
     inline-block keeps inner inline layout (cf. inline-flex which recenters items). */
  display: inline-block;
  vertical-align: baseline;
  border-radius: 6px;
  outline: 1px dashed cyan;
  outline-offset: 2px;
}
.obj-bar-vue-control {
  display: inline-block;
  vertical-align: middle;
}
.obj-bar .form-range {
  width: 125px;
  padding-top:15px;
  padding-left: 3px;
}
.obj-bar .form-range::-webkit-slider-thumb {
  background: gray;
  border: 2px solid white;
}
.obj-bar .form-range::-moz-range-thumb {
  background: gray;
  border: 2px solid white;
}
.obj-bar .form-range::-ms-thumb {
  background: gray;
  border: 2px solid white;
}
.obj-bar .form-range::-webkit-slider-runnable-track {
  background: rgba(255,255,255, 0.5);
}
.obj-bar .form-range::-moz-range-track {
  background-color: rgba(255,255,255, 0.5);
}
.obj-bar-editable {
  color: white;
  background-color: rgba(255,255,255,0.2);
  border: none;
  text-align: center;
}
.obj-bar-editable::selection {
  background-color: gray;
  color: white;
}
.obj-bar-number {
  width: 40px;
  padding-left: 1px;
  padding-right: 1px;
  font-size: 15px;
}
.mq-cursor {
  border-color: white !important;
}
.info-icon {
  color: rgba(255, 255, 255, 0.6);
  padding-left:0px;
  padding-right:0px;
}
.obj-bar .form-switch .form-check-input {
  margin-top: 0px;
  background-color: rgba(255,255,255, 0.3);
  border: none;
  vertical-align: middle;
}
.obj-bar .form-switch .form-check-input {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
}
.obj-bar .form-switch .form-check-input:focus {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_1___});
}
.obj-bar .form-switch .form-check-input:checked {
  background-color: gray;
  border: none;
}
.obj-bar .form-switch .form-check-input:checked {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_1___});
}
.obj-bar .form-switch .form-check-input:checked:focus {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_1___});
}

/* Dummy width before "More options" while advanced controls load (obj_bar_main is non-Vue). */
.obj-bar-advanced-expand-spacer {
  display: inline-block;
  width: 0;
  overflow: hidden;
  vertical-align: middle;
  /* ease-in: accelerates toward the end so motion does not ease into the dummy width */
  transition: width 0.28s cubic-bezier(0.55, 0, 1, 1);
  pointer-events: none;
}
.obj-bar-advanced-expand-spacer--open {
  width: 200px;
}
#showAdvanced {
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.15rem;
  padding-right: 0.15rem;
}
#showAdvanced .obj-bar-more-options-chevron {
  flex-shrink: 0;
}
#showAdvanced .obj-bar-more-options-label,
#showAdvanced .obj-bar-more-options-chevron {
  color: rgba(255, 255, 255, 0.65);
}
#showAdvanced .obj-bar-more-options-label {
  font-style: normal;
}
#showAdvanced:hover .obj-bar-more-options-label,
#showAdvanced:hover .obj-bar-more-options-chevron {
  color: rgba(255, 255, 255, 0.8);
}
